examples.call:
u.animation("fade-in", {
  keyframes: {
    from: { opacity: 0 },
    to: { opacity: 1 },
  },
  duration: "150ms",
  easing: "ease-out",
});

examples.output:
css({
  "@keyframes fade-in": { from: { opacity: 0 }, to: { opacity: 1 } },
  animationName: "fade-in",
  animationDuration: "150ms",
  animationTimingFunction: "ease-out",
})

examples.call:
